/* The Planner — Act II: The Plans (1924–1938).
   Spine (Dalby): Peckham, Poland 1926, the General Strike, Bishop Auckland 1929 after Ruth, the Foreign
   Office under Hendry 1929–31, the 1931 split (a rogue fork: follow MacDougal), the XYZ Club and the New
   Fabian Research Bureau, Practical Socialism 1935, party chairman 1936–37, Spain, the arms estimates 1937.
   Routes: the patent Bar (Crisp: Solicitor General 1930, Bristol East 1931, the Socialist League, the 1936
   remark, Unity 1937), the WEA tutor (Gaskell and Dunbar: 1926, the NFRB, Vienna 1934 as a rogue fork,
   Gillingham 1935, the Immediate Programme 1937), the grammar-school life (Wilmot: Beverley's assistant).
   Sources: RESEARCH.md, "Planner figures, re-read 11 Nov 2026". */
(function () {
  const TM = window.TM;
  const PLAN = TM.PLAN_SPINE;
  const LIVE = '~!fork-national31 ~!fork-vienna34';

  Object.assign(TM.PEOPLE, {
    macdougal: { name: 'Mr MacDougal', role: 'Leader of the Labour Party; Prime Minister 1924 and 1929–31' },
    gaskell: { name: 'Hugh Gaskell', role: 'A young Wykehamist economist' },
    dunbar: { name: 'Evan Dunbar', role: 'A Baptist minister\'s son who lectures at the LSE' },
    jagger: { name: 'Douglas Jagger', role: 'A journalist and Fellow of All Souls' },
    beverley: { name: 'Sir William Beverley', role: 'Master of University College, Oxford' },
  });

  TM.FORKS.national31 = {
    title: 'National Labour',
    history: 'In August 1931, when the Labour Cabinet split over cuts in unemployment benefit, a clever young Labour minister followed Mr MacDougal into the National Government. He kept his seat in October as a National Labour candidate, with the Conservatives standing aside, and was rewarded with a junior post. His old party called him a rat. By 1935 the Conservatives no longer needed him, and the National Labour group dwindled to a handful of men with titles and no followers.',
    more: [],
    real: 'Hugh Dalton stayed with the Labour Party in 1931, voted to expel MacDonald, and lost Bishop Auckland in the landslide. National Labour, MacDonald\'s group, won thirteen seats in 1931 and eight in 1935.',
    ends: { 2: { head: 'The National Labour man', text: '1938. {first} {last} is {age}, a junior minister in a government that does not need him, cut in the street by men he used to call comrade.' } },
  };

  TM.FORKS.vienna34 = {
    title: 'The Karl-Marx-Hof',
    history: 'In February 1934, when the Austrian government turned its guns on the workers\' flats of Vienna, a young English economist on a scholarship there took a rifle and went into the Karl-Marx-Hof with the Schutzbund. He was arrested when the building fell, held for four months and expelled. He went to Moscow in 1935, came back disillusioned in 1937, and spent the war in a government department that did not ask about his past. He never stood for Parliament.',
    more: [],
    real: 'Hugh Gaitskell was in Vienna on a Rockefeller scholarship in February 1934 and saw the socialists crushed by the Dollfuss government. He helped socialists escape afterwards and came home a convinced democratic socialist and anti-fascist.',
    ends: { 2: { head: 'After Vienna', text: '1938. {first} {last} is {age}, a statistician in a back room, with a police file in Vienna and a closed door in Transport House.' } },
  };

  TM.ACTS.planner[2] = {
    title: 'Act II · The Plans',
    span: '1924–1938',
    regen: 2,
    continues: 'Act III of this life, from Munich to 1951, is still being written, so this life ends here for now.',
    intro: 'Labour has governed for nine months and been thrown out. The trade union men who run the party think economists are a luxury; the economists think the trade union men have no plan. Unemployment will not fall below a million for fifteen years. Somebody will have to work out what a Labour government should actually do with power, down to the last pound. It might as well be you.',
    end: (s) => {
      const age = s.year - s.born;
      if (s.flags.includes('route-grammar')) return { head: 'The young statistician', text: '1938. {first} {last} is ' + age + ', a lecturer and Sir William Beverley\'s assistant, who can make a table of figures tell a story. Nobody has heard of him.' };
      if (s.flags.includes('mp')) return { head: 'The Member for {seat}', text: '1938. {first} {last} is ' + age + ', the Labour Member for {seat}, with a plan for everything: the banks, the mines, the land, the arms, and the men to carry it out.' };
      return { head: 'The planner without a seat', text: '1938. {first} {last} is ' + age + ', without a seat but not without influence: in a dozen committee rooms the plans are his.' };
    },
    start: { year: 1924 },

    scenes: [
      /* ═══════ Dalby: the economist Member ═══════ */
      { id: 'poland-1926', year: 1926, t: 1926.3, title: 'A map of Silesia', if: PLAN + ' !mp ' + LIVE,
        venue: { plate: 'city', label: 'A hotel in Katowice, Upper Silesia' },
        text: 'April 1926. You are touring Poland for the party with a map, a notebook and an interpreter. In Upper Silesia the frontier drawn by the League runs through villages and mines; Poles live on the German side and Germans on the Polish. Every district is a quarrel waiting for an army. A German mine manager says the only cure is to move the people. A Polish priest says that is how wars start.',
        basis: 'Dalton\'s visit to Poland in 1926, which convinced him the disputed regions were too mixed for a clean border; his early support for transfers of population, and his book Towards the Peace of Nations (1928).',
        real: 'After visiting Poland in 1926 Dalton concluded that the mixed frontier regions could not be divided cleanly, and in Towards the Peace of Nations (1928) he praised the Greek–Turkish population exchange of 1922–23. Such ideas were carried out with great cruelty after 1945.',
        check: 'research', facts: ['dalton-1924-38'],
        choices: [
          { label: 'Write that the peoples must be separated', effects: 'steel+2 empire+1 cap+2', historical: true,
            result: 'Your book says that exchanges of population, properly done, are the price of peace. It is praised in the reviews. It will read differently twenty years later.',
            diary: 'Exchanges of population. Praised.' },
          { label: 'Write for minority rights under the League', effects: 'state+1 empire-2 cap+2',
            result: 'You argue for League guarantees for the minorities. The Germans and the Poles both say the League is useless.',
            diary: 'Minority rights. Both sides scoff.' },
          { label: 'Come home and say nothing about it', effects: 'fav+1',
            result: 'The notebook goes in a drawer. Silesia will be fought over anyway.',
            diary: 'The notebook in a drawer.' },
        ] },

      { id: 'general-strike-plan', year: 1926, t: 1926.35, title: 'Nine days in May', if: '~!route-grammar ' + LIVE,
        venue: { plate: 'city', label: 'The TUC offices, Eccleston Square' },
        text: 'May 1926. The General Strike has begun: no trains, no buses, no newspapers but the government\'s and the TUC\'s. Volunteers from the universities are driving the trams. Labour\'s leaders are terrified of it and the TUC wants it over. You have a car and some friends. Some young Oxford men are driving the strike committee\'s messengers around the country. A Cabinet minister\'s wife asks you to drive a bus.',
        basis: 'The General Strike of 3–12 May 1926; Hugh Gaitskell, then at Oxford, drove for the strikers, carrying Evan Durbin and Margaret Cole; Dalton, as a Labour MP, supported the miners.',
        real: 'The General Strike lasted from 3 to 12 May 1926. Undergraduates volunteered on both sides. Gaitskell supported the strikers and drove for the TUC, which is how he met Durbin, and spent months afterwards raising money for the miners.',
        check: 'research', facts: ['general-strike-1926', 'gaitskell-early'],
        choices: [
          { label: 'Drive for the strike committee', effects: 'state+3 order-2 @gaskell+5 @dunbar+3', historical: true,
            result: 'You drive a lanky young Wykehamist and a minister\'s son round the Midlands with the strike bulletin. They argue about Mr Kaine all the way. They will be friends for life.',
            diary: 'Drove the bulletin. Gaskell and Dunbar.' },
          { label: 'Raise money for the miners\' families', effects: 'state+2 cap+2 money-3',
            result: 'You raise four hundred pounds in a week from people who would never admit it.',
            diary: 'Four hundred pounds.' },
          { label: 'Stay out of it: a general strike is a mistake', effects: 'order+2 loyalty+1',
            result: 'You say so, privately. When it collapses after nine days you are right, and you take no pleasure in it.',
            diary: 'Right, and no pleasure in it.' },
        ] },

      { id: 'bishop-auckland-1929', year: 1929, t: 1929.4, title: 'Ruth\'s seat', if: PLAN + ' !mp ' + LIVE,
        venue: { plate: 'mill', label: 'Bishop Auckland, County Durham' },
        text: 'May 1929. Bishop Auckland is a Durham mining seat with a Labour majority as solid as the pit heaps. Its Member died in January, and the party asked Ruth to hold it at the by-election for a few months until the general election, so that you could move in from marginal Peckham. She won it handsomely. Now she is to stand down for you. She says she likes the House more than she expected.',
        basis: 'Ruth Dalton won the Bishop Auckland by-election in February 1929 and held the seat until the general election of May 1929, when Hugh Dalton succeeded her.',
        real: 'Ruth Dalton held Bishop Auckland for Labour from the by-election of February 1929 until the general election that May, when her husband took the seat. She went on to a career on the London County Council.',
        check: 'unchecked', facts: ['dalton-1924-38'],
        choices: [
          { label: 'Take the seat as agreed', effects: 'fav+2 seat+15 @ruth-3 set:seat=Bishop_Auckland', historical: true,
            result: 'You are elected for Bishop Auckland with a large majority. Ruth goes on to the London County Council and is good at it.',
            diary: 'Bishop Auckland. Ruth to the LCC.' },
          { label: 'Tell her to keep it, and stay in Peckham', effects: 'state+1 @ruth+8',
            roll: { stat: 'seat', diff: 25,
              pass: { effects: 'rep+2', result: 'You both win. Two Daltons in the House is a joke in the smoking room for a week, then a fact.', diary: 'Both of us in.' },
              fail: { effects: '-!mp rep-2', result: 'Ruth wins Bishop Auckland. You lose Peckham.', diary: 'Ruth in. Me out.' } } },
          { label: 'Take it, and promise her the next safe seat', effects: 'fav+1 seat+15 @ruth+2 set:seat=Bishop_Auckland',
            result: 'You win Bishop Auckland. The next safe seat goes to a miners\' official, as always.',
            diary: 'Bishop Auckland. The promise not kept.' },
        ] },

      { id: 'foreign-office-1929', year: 1929, t: 1929.6, title: 'Under-Secretary', if: PLAN + ' !mp ' + LIVE,
        venue: { plate: 'whitehall', label: 'The Foreign Office, King Charles Street' },
        text: 'June 1929. Labour is back, and Mr Hendry, your patron, is Foreign Secretary. He has made you his Parliamentary Under-Secretary: you will answer for the Foreign Office in the Commons. The permanent officials are polite and think Labour ministers temporary. The great question is whether to restore relations with Soviet Russia, broken off in 1927. Hendry wants it done. The officials want conditions.',
        basis: 'Dalton as Parliamentary Under-Secretary for Foreign Affairs under Arthur Henderson, June 1929 to August 1931; the restoration of diplomatic relations with the Soviet Union in 1929.',
        real: 'Dalton served as Under-Secretary at the Foreign Office from June 1929 to August 1931 under Arthur Henderson. Relations with the Soviet Union, broken off in 1927, were restored in late 1929.',
        check: 'unchecked', facts: ['dalton-1924-38', 'soviet-relations-1929'],
        choices: [
          { label: 'Push Hendry\'s line through the office', effects: 'state+2 fav+3 @hendry+5 office=Under-Secretary_for_Foreign_Affairs !junior', historical: true,
            result: 'Relations are restored by the end of the year. The officials learn that you read the files.',
            diary: 'Relations restored. They know I read the files.' },
          { label: 'Make your name at the despatch box', effects: 'press+3 cap+2 office=Under-Secretary_for_Foreign_Affairs !junior',
            result: 'Your voice fills the chamber. The Opposition complain that you shout. The press like it.',
            diary: 'They say I shout.' },
          { label: 'Concentrate on disarmament and the League', effects: 'empire-2 steel-1 cap+2 office=Under-Secretary_for_Foreign_Affairs !junior',
            result: 'You spend months in Geneva. You come back thinking disarmament will not happen while there are dictators.',
            diary: 'Geneva. No disarmament with dictators.' },
        ] },

      { id: 'crisis-1931-plan', year: 1931, t: 1931.65, title: 'August 1931', if: '!junior ' + LIVE,
        venue: { plate: 'whitehall', label: 'Transport House, Smith Square' },
        text: 'August 1931. The pound is falling, the bankers want the dole cut by a tenth, and the Cabinet has split. Mr MacDougal has gone to the Palace and come back as Prime Minister of a National Government with the Tories and the Liberals. He has asked a few of the cleverer junior ministers to come with him. A note from Downing Street asks if you will stay at your post.',
        basis: 'The crisis of August 1931 and the formation of the National Government on 24 August; Dalton refused to follow MacDonald and later voted for his expulsion.',
        real: 'On 24 August 1931 MacDonald formed a National Government. Almost all Labour ministers went into opposition; only a few, including Snowden, Thomas and Sankey, followed him. Dalton stayed with Labour, voted to expel MacDonald, and lost his seat that October.',
        check: 'research', facts: ['august-1931', 'dalton-1924-38'],
        choices: [
          { label: 'Refuse, and stay with the party', effects: 'loyalty+4 state+2 -!junior office=None', historical: true,
            result: 'You write a two-line reply. At the party meeting you vote to expel MacDougal. Few others go with him.',
            diary: 'Refused. Voted to expel him.' },
          { label: 'Stay at your post with MacDougal', effects: 'order+3 loyalty-6 fav+4 fork=national31',
            result: 'You stay at the Foreign Office under a Liberal Foreign Secretary. Your old friends stop speaking to you in the corridors.',
            diary: 'Stayed. They do not speak to me.' },
          { label: 'Ask for a week to think', effects: 'fav-2 loyalty+1 -!junior office=None',
            result: 'The week answers itself: the Labour Party goes into opposition and so do you.',
            diary: 'The week decided for me.' },
        ] },

      { id: 'election-1931-plan', year: 1931, t: 1931.8, title: 'The rout', if: '!mp ~!route-patents ' + LIVE,
        venue: { plate: 'mill', label: 'The count, {seat}' },
        text: 'October 1931. The National Government says Labour would spend your savings; Mr Snowdon, Labour\'s own former Chancellor, calls the party\'s programme Bolshevism run mad. In {seat} your agent says the miners will hold, but the shopkeepers and the chapel will not, and the women are frightened for the Post Office savings. The swing everywhere is enormous. Old colleagues are standing against you as National Labour. The count is tonight, in a cold school hall.',
        basis: 'The general election of 27 October 1931, in which Labour fell to 52 seats; Dalton lost Bishop Auckland; Cripps held Bristol East.',
        real: 'Labour won only 52 seats in October 1931. Dalton lost Bishop Auckland narrowly. Cripps, one of only three former Labour ministers to keep their seats, held Bristol East.',
        check: 'research', facts: ['election-1931', 'dalton-1924-38'],
        choices: [
          { label: 'Fight on the record and the bankers\' ramp', effects: 'state+2 loyalty+2', historical: true,
            roll: { stat: 'seat', diff: 55,
              pass: { effects: 'rep+5', result: 'You hold {seat}, one of fifty-two. The survivors meet in a single committee room.', diary: 'Held. One of fifty-two.' },
              fail: { effects: '-!mp rep-2 office=None', result: 'You lose by a few hundred votes. It is a massacre everywhere.', diary: 'Lost. A massacre.' } } },
          { label: 'Fight on your own name', effects: 'press+2 loyalty-1',
            roll: { stat: 'reputation', diff: 50,
              pass: { effects: 'rep+3', result: 'Your own vote holds.', diary: 'My own vote held.' },
              fail: { effects: '-!mp rep-2 office=None', result: 'Nobody votes for names this year. You lose.', diary: 'Lost.' } } },
          { label: 'Use the defeat: there will be time to plan', effects: 'cap+2 health+2 -!mp office=None',
            result: 'You lose, and you are not sorry to have four years to think.',
            diary: 'Four years to think.' },
        ] },

      { id: 'xyz-1932', year: 1932, title: 'The XYZ Club', if: '~!route-grammar ~!route-patents ' + LIVE,
        venue: { plate: 'club', label: 'A private room in a City restaurant' },
        text: '1932. Once a month a dozen men meet over dinner in the City: a stockbroker, two bankers who vote Labour in secret, journalists, young economists. They call it the XYZ Club. The question is the one that wrecked the last Labour government: what to do about the banks and the pound when the City panics. Douglas Jagger brings figures. Hugh Gaskell brings Mr Kaine. They want a chairman who can get plans to the party.',
        basis: 'The XYZ Club, a dining club of Labour-sympathising City men and economists formed in the early 1930s; Dalton, Gaitskell, Jay and Durbin took part; the New Fabian Research Bureau (1931) under G. D. H. Cole.',
        real: 'The XYZ Club, founded in 1932, brought Labour sympathisers in the City together with young economists such as Gaitskell, Jay and Durbin to work on financial policy. Dalton used it and the New Fabian Research Bureau to prepare Labour\'s plans for the banks and the Bank of England.',
        check: 'unchecked', facts: ['planner-xyz'],
        choices: [
          { label: 'Chair it and turn it into policy', effects: 'state+3 cap+4 @gaskell+4 @jagger+4', historical: true,
            result: 'Within three years the party is committed to nationalising the Bank of England and controlling investment. The plans are yours, and the young men\'s.',
            diary: 'The Bank of England. Plans.' },
          { label: 'Go for the arguments and the claret', effects: 'cap+2 money-2 health-1',
            result: 'You learn how the City thinks, which is not at all how it says it thinks.',
            diary: 'How the City thinks.' },
          { label: 'Bring Mr Cole\'s research bureau in with it', effects: 'state+2 cap+3',
            result: 'The New Fabian Research Bureau produces thirty pamphlets in two years. Some are even read.',
            diary: 'Thirty pamphlets.' },
        ] },

      { id: 'practical-1935', year: 1935, t: 1935.2, title: 'Practical socialism', if: PLAN + ' ' + LIVE,
        venue: { plate: 'whitehall', label: 'Your flat in Carlisle Mansions, Victoria' },
        text: 'March 1935. Your book is finished: a plan, costed, for what a Labour government would do in its first five years. Nationalise the Bank of England, coal, power and transport; a National Investment Board; land for the nation; higher death duties. No talk of the barricades. The left will call it timid and the City will call it confiscation. Your publisher wants a title that will sell.',
        basis: 'Dalton\'s Practical Socialism for Britain (1935), a detailed programme that strongly influenced Labour\'s plans and Attlee.',
        real: 'Dalton\'s Practical Socialism for Britain appeared in March 1935. Ben Pimlott called it "the first swallow of the post-1935 summer"; it set out much of the programme Labour carried out after 1945.',
        check: 'research', facts: ['dalton-1924-38'],
        choices: [
          { label: 'Call it Practical Socialism', effects: 'state+3 order+1 cap+3', historical: true,
            result: 'It sells modestly and is read by everyone who matters in the party. The left calls it timid.',
            diary: 'Practical Socialism. Timid, they say.' },
          { label: 'Make it more radical to win the left', effects: 'state+4 order-2 temper+2',
            result: 'The left cheers and the unions get nervous. It sells better.',
            diary: 'More radical. Sold better.' },
          { label: 'Cut it down to a pamphlet for the voters', effects: 'press+3 cap+1',
            result: 'A hundred thousand copies at twopence. The ideas spread further than the book would have.',
            diary: 'A hundred thousand at twopence.' },
        ] },

      { id: 'election-1935-plan', year: 1935, t: 1935.85, title: 'November 1935', if: PLAN + ' ~!mp ' + LIVE,
        venue: { plate: 'mill', label: 'The count, {seat}' },
        text: 'November 1935. The National Government is going to the country promising support for the League of Nations and a little rearmament. Labour is led by a quiet Major after the old pacifist resigned at the party conference. In {seat} the pits have been on short time for years, and the men have not forgotten 1931 or the means test. You are standing again, with Practical Socialism in your pocket.',
        basis: 'The general election of 14 November 1935; Attlee succeeded Lansbury as Labour leader in October 1935; Dalton regained Bishop Auckland.',
        real: 'Labour won 154 seats in November 1935. Dalton recovered Bishop Auckland and held it until 1959. Attlee, who had replaced Lansbury as leader in October 1935, was confirmed as leader after the election.',
        check: 'research', facts: ['dalton-1924-38'],
        choices: [
          { label: 'Fight on jobs and the means test', effects: 'state+2 health-1', historical: true,
            roll: { stat: 'seat', diff: -10,
              pass: { effects: 'rep+3 !mp office=Member_for_{seat}', result: 'You win {seat} back with a big majority.', diary: 'Back in. {seat}.' },
              fail: { effects: 'rep-2', result: 'You lose again, narrowly. The Tory is a good local man.', diary: 'Lost again.' } } },
          { label: 'Fight on rearmament against Hitler', effects: 'steel+3 loyalty-1',
            roll: { stat: 'reputation', diff: 10,
              pass: { effects: 'rep+2 !mp office=Member_for_{seat}', result: 'The miners like a man who calls Hitler what he is. You win.', diary: 'Won. Hitler called what he is.' },
              fail: { effects: 'rep-2', result: 'The chapel does not want to hear about guns. You lose.', diary: 'The chapel wanted peace. Lost.' } } },
          { label: 'Stay in the back room and plan', effects: 'cap+3',
            result: 'You do not stand. The plans improve. Your career does not.',
            diary: 'The back room.' },
        ] },

      { id: 'arms-1937', year: 1937, t: 1937.55, title: 'The arms estimates', if: PLAN + ' !mp ' + LIVE,
        venue: { plate: 'gallery', label: 'Committee Room 14, House of Commons' },
        text: 'July 1937. Every year the Labour Party votes against the government\'s arms estimates, because it does not trust the government with the arms. Hitler has the Rhineland and Spain is burning. You think it absurd to vote against guns while demanding that Hitler be stopped. Tonight the parliamentary party meets to decide. Bevis is with you. The pacifists and Mr Crisp\'s friends are not.',
        basis: 'Dalton\'s successful campaign in July 1937 to persuade the Parliamentary Labour Party to abstain, rather than vote against, the service estimates; his alliance with Bevin on rearmament.',
        real: 'In July 1937 Dalton, as chairman of the party, persuaded the Parliamentary Labour Party by 45 votes to 39 to abstain on the arms estimates instead of voting against, a turning point in Labour\'s acceptance of rearmament. Pimlott records Dalton and Bevin as the first leaders to press it.',
        check: 'unchecked', facts: ['arms-1937', 'dalton-1924-38'],
        choices: [
          { label: 'Move that the party abstain', effects: 'steel+3 loyalty+1 @bevis+4', historical: true,
            roll: { stat: 'capital', diff: 25,
              pass: { effects: 'rep+4', result: 'You carry it by six votes. Labour will not vote against the guns again. The pacifists never forgive you.', diary: 'Carried by six. No more votes against guns.' },
              fail: { effects: 'rep-1', result: 'You lose by four. Labour votes against the estimates once more. Hitler reads the division list.', diary: 'Lost by four.' } } },
          { label: 'Move that the party vote for them', effects: 'steel+4 loyalty-3',
            result: 'You are heavily defeated. The left calls you a warmonger. You were right too soon.',
            diary: 'Warmonger, they say.' },
          { label: 'Let it go: unity matters more', effects: 'loyalty+3 steel-2',
            result: 'Labour votes against the estimates again. The party is united and wrong.',
            diary: 'United and wrong.' },
        ] },

      { id: 'chairman-1936', year: 1936, t: 1936.75, title: 'The party chairman', if: PLAN + ' !mp ' + LIVE,
        venue: { plate: 'city', label: 'The Labour Party conference, Edinburgh' },
        text: 'October 1936. You have been elected chairman of the Labour Party for the coming year, and conference is in uproar over Spain. The government\'s policy of non-intervention starves the Spanish Republic of arms while Hitler and Mussolini supply Franco. The French socialist premier, M. Blum, asked you in Paris last month to hold British Labour to non-intervention. The delegates want arms for Spain.',
        basis: 'Dalton was chairman of the Labour Party from October 1936 to October 1937; he visited Léon Blum in Paris in September 1936 and was wary of "arms for Spain".',
        real: 'Dalton chaired the Labour Party in 1936–37. He met Léon Blum in September 1936 and supported non-intervention at first; the party turned against it in 1937.',
        check: 'research', facts: ['dalton-1924-38', 'international-brigades'],
        choices: [
          { label: 'Hold to non-intervention for now', effects: 'order+1 loyalty+2 steel-1', historical: true,
            result: 'Conference narrowly backs the leadership. The Spanish delegates weep in the gallery. Within a year the party reverses itself.',
            diary: 'Non-intervention. They wept.' },
          { label: 'Back arms for the Republic', effects: 'steel+3 state+1 @blum-3',
            result: 'You carry the hall and annoy the French. The government ignores both.',
            diary: 'Arms for Spain. Ignored.' },
          { label: 'Use the chair to push rearmament instead', effects: 'steel+2 cap+2',
            result: 'You turn the debate towards Hitler. Bevis backs you. It is the start of something.',
            diary: 'Turned it to Hitler.' },
        ] },

      /* ═══════ Crisp: the patent Bar goes red ═══════ */
      { id: 'solicitor-1930', year: 1930, t: 1930.8, title: 'Solicitor General', if: '!route-patents ' + LIVE,
        venue: { plate: 'whitehall', label: 'The Law Officers\' Department, the Strand' },
        text: 'October 1930. Mr MacDougal needs a Solicitor General, and the Labour Party has no barristers worth the name. Mr Morrow, who knows you through your uncle, suggests you: rich, brilliant, a churchman, and a party member for a few months. The post carries a knighthood and requires a seat. Bristol East is about to fall vacant. Your clerks say you will lose ten thousand a year.',
        basis: 'Cripps joined Labour in 1930 and was appointed Solicitor General in October 1930, knighted, and elected for Bristol East at a by-election on 16 January 1931.',
        real: 'Stafford Cripps became Solicitor General in October 1930, was knighted, and entered the Commons at the Bristol East by-election of 16 January 1931. He held the seat in the 1931 rout.',
        check: 'research', facts: ['cripps-early', 'cripps-1930s'],
        choices: [
          { label: 'Accept, and fight Bristol East', effects: 'state+3 money-8 fav+3 office=Solicitor_General !junior', historical: true,
            roll: { stat: 'capital', diff: -20,
              pass: { effects: 'rep+3 seat+12 !mp', result: 'You win the by-election comfortably. Sir {last}, the Member for Bristol East.', diary: 'Bristol East. Sir now.' },
              fail: { effects: 'rep-2 -!junior office=None', result: 'You lose the by-election to a Liberal. The post goes to someone else.', diary: 'Lost Bristol. The post gone.' } } },
          { label: 'Decline: the practice is your life', effects: 'money+6 order+1',
            result: 'You stay at the Bar. Two years later the party asks again.',
            diary: 'Declined.' },
          { label: 'Accept, but keep a few big briefs', effects: 'money+2 state+1 fav-2 office=Solicitor_General !junior !mp seat+10',
            result: 'You are elected for Bristol East. The newspapers notice the briefs.',
            diary: 'Bristol East. The briefs noticed.' },
        ] },

      { id: 'socialist-league-1932', year: 1932, t: 1932.7, title: 'The Socialist League', if: '!route-patents ' + LIVE,
        venue: { plate: 'city', label: 'A hall in Leicester' },
        text: 'October 1932. You held Bristol East in the rout of 1931, one of a tiny band. After 1931 you are sure the bankers will wreck any Labour government again unless it moves fast: an Emergency Powers Act on the first day, the Lords abolished, the banks taken over. The ILP has left the Labour Party; its cleverer members want a new society inside it, the Socialist League, and they want you to lead it. Mr Astley says it will split the party.',
        basis: 'Cripps founded and led the Socialist League from 1932, proposing an Emergency Powers Act and abolition of the House of Lords; he was its chairman 1933–36.',
        real: 'The Socialist League was formed in 1932 from ILP members who stayed in the Labour Party. Cripps led it and argued that a Labour government must take emergency powers to overcome the resistance of capital. Attlee and Dalton thought it reckless.',
        check: 'research', facts: ['cripps-1930s'],
        choices: [
          { label: 'Lead it', effects: 'state+4 order-3 loyalty-3 press+3', historical: true,
            result: 'You are the hero of the constituency parties and the despair of Transport House. Your speeches are reported everywhere, often to the party\'s cost.',
            diary: 'The League. Hero and despair.' },
          { label: 'Join, but keep out of the chair', effects: 'state+2 loyalty-1',
            result: 'You write its pamphlets. They are clever and frightening.',
            diary: 'The pamphlets.' },
          { label: 'Stay with Mr Astley in the parliamentary party', effects: 'loyalty+3 state+1 @astley+4',
            result: 'You become the best debater on Labour\'s tiny front bench. Astley relies on you.',
            diary: 'Astley relies on me.' },
        ] },

      { id: 'remark-1936', year: 1936, t: 1936.1, title: 'A careless sentence', if: '!route-patents ' + LIVE,
        venue: { plate: 'city', label: 'A meeting hall, Stockport' },
        text: 'January 1936. The hall is hot and the questions are hostile. A man asks whether socialists would fight for the Empire against Hitler. You are tired, and you believe that capitalist Britain and capitalist Germany are much the same. A sentence comes to your lips: that it would not be a bad thing for the working class if British capitalism were defeated. The reporters are writing.',
        basis: 'Cripps\'s remark in 1936 that he did not believe it would be a bad thing for the British working class if Germany defeated Britain; the National Executive dissociated the party from it; Dalton called it the judgement of a flea.',
        real: 'In 1936 Cripps said in a speech that he did not believe it would be a bad thing for the British working class if Germany defeated Britain. The Labour Party\'s National Executive publicly dissociated itself. Dalton privately mocked his judgement.',
        check: 'research', facts: ['cripps-1930s'],
        choices: [
          { label: 'Say it', effects: 'state+2 empire-4 loyalty-4 press+2 rep-3', historical: true,
            result: 'It is on every front page by morning. The party\'s Executive disowns you. Mr Dalby calls it the judgement of a flea. You do not apologise.',
            diary: 'Said it. The judgement of a flea.' },
          { label: 'Bite it back and talk about Spain', effects: 'cap+2 steel+1',
            result: 'You talk about the Spanish Republic instead. The hall cheers. Nothing is reported.',
            diary: 'Talked about Spain.' },
          { label: 'Say that socialists will fight fascism anywhere', effects: 'steel+3 empire+1 state+1',
            result: 'The man in the cloth cap nods. A reporter writes it down. Mr Dalby, reading it, is surprised.',
            diary: 'We will fight fascism.' },
        ] },

      { id: 'unity-1937-plan', year: 1937, t: 1937.1, title: 'Unity', if: '!route-patents ' + LIVE,
        venue: { plate: 'city', label: 'The Free Trade Hall, Manchester' },
        text: 'January 1937. A Unity Campaign: the Socialist League, the ILP and the Communists on one platform against fascism and the National Government. You have put up the money for a weekly paper, Tribune, to argue for it. The Labour Party Executive has said that members of the League who share a platform with Communists will be expelled. The hall is full. The platform is waiting.',
        basis: 'The Unity Campaign of 1937 (Socialist League, ILP and Communist Party); the founding of Tribune; the League dissolved itself in 1937 rather than face expulsion; Cripps was expelled in early 1939 over the Popular Front.',
        real: 'The Unity Campaign was launched in January 1937. The Labour Executive disaffiliated the Socialist League, which dissolved itself in May 1937. Cripps was expelled from the Labour Party in January 1939 for advocating a Popular Front, and readmitted in 1945.',
        check: 'research', facts: ['cripps-1930s'],
        choices: [
          { label: 'Go on the platform', effects: 'state+3 loyalty-4 press+2 #unity', historical: true,
            result: 'You speak with Mr Pollard of the Communists. The League is disaffiliated. You dissolve it to save its members. You yourself are marked.',
            diary: 'The platform. Marked.' },
          { label: 'Send a message of support but stay off', effects: 'state+1 loyalty-1',
            result: 'The left thinks you have lost your nerve. The Executive thinks you are on probation.',
            diary: 'A message. On probation.' },
          { label: 'Call it off and stay in the party', effects: 'loyalty+4 state-1',
            result: 'The left calls you a traitor. You stay inside, which is where the power is.',
            diary: 'Called it off.' },
        ] },

      /* ═══════ The WEA tutor: Gaskell and Dunbar ═══════ */
      { id: 'nfrb-1931', year: 1931, t: 1931.3, title: 'The research bureau', if: '!route-wea ' + LIVE,
        venue: { plate: 'school', label: 'Mr Cole\'s house, Oxford' },
        text: 'March 1931. Mr Cole, the Oxford economist, has gathered his clever young men to start a New Fabian Research Bureau: proper research into what socialists would actually do, since the government in office plainly has no idea. Hugh Gaskell and Evan Dunbar are there, both younger than you and both cleverer, they think. Cole wants someone who knows the coalfields to run the industrial side.',
        basis: 'The New Fabian Research Bureau, set up by G. D. H. Cole in March 1931; Gaitskell helped run it; Durbin and Gaitskell were part of the "Cole group".',
        real: 'G. D. H. Cole founded the New Fabian Research Bureau in March 1931 to work out practical socialist policy. Gaitskell and Durbin were among its young economists; it merged with the Fabian Society in 1939.',
        check: 'unchecked', facts: ['planner-xyz', 'gaitskell-early'],
        choices: [
          { label: 'Run the industrial side', effects: 'state+3 cap+3 @gaskell+3 @dunbar+3', historical: true,
            result: 'You write the Bureau\'s plan for coal: one national board, compensation for the owners, a say for the men. It will be used, in time.',
            diary: 'The coal plan. In time.' },
          { label: 'Stay a tutor: the men come first', effects: 'state+2 health+1',
            result: 'You keep your classes. Gaskell says you are the only one of them who knows any miners.',
            diary: 'The classes. Gaskell envies me.' },
          { label: 'Stand for Parliament in the autumn', effects: 'cap+2 loyalty+2',
            result: 'You are adopted for East Grinstead, a Tory fortress. Gaskell speaks for you. You lose by twenty thousand, cheerfully.',
            diary: 'East Grinstead. Lost cheerfully.' },
        ] },

      { id: 'vienna-1934', year: 1934, t: 1934.12, title: 'The Karl-Marx-Hof', if: '!route-wea ' + LIVE,
        venue: { plate: 'city', label: 'The Karl-Marx-Hof, Vienna' },
        text: 'February 1934. You are in Vienna on a research scholarship when the government turns its artillery on the workers\' flats. The socialists\' defence corps holds out in the Karl-Marx-Hof, the great housing estate that was the pride of Red Vienna. Shells are falling on the apartments where children live. A socialist you know asks you to carry passports for men on the run. Another hands you a rifle.',
        basis: 'Gaitskell\'s year in Vienna on a Rockefeller scholarship, 1933–34, when he witnessed the crushing of the Austrian socialists by Dollfuss in February 1934 and helped socialists escape.',
        real: 'In February 1934 the Dollfuss government crushed the Austrian Social Democrats after four days of fighting, shelling the Karl-Marx-Hof. Gaitskell, in Vienna on a Rockefeller scholarship, helped socialists escape and came home a determined anti-fascist.',
        check: 'research', facts: ['gaitskell-early'],
        choices: [
          { label: 'Carry the passports', effects: 'state+3 steel+3 health-1 #vienna', historical: true,
            roll: { stat: 'health', diff: 20,
              pass: { effects: 'rep+2', result: 'You get four men over the Czech frontier in a hired car. You never talk about it in England.', diary: 'Four men over the frontier.' },
              fail: { effects: 'rep-1 health-2', result: 'The police stop you at the station and take the passports. You are put on a train to Paris. The men are caught.', diary: 'Stopped. The men caught.' } } },
          { label: 'Take the rifle', effects: 'steel+5 temper+4 order-3',
            death: { chance: 0.12, text: 'You were killed in the Karl-Marx-Hof in Vienna in February 1934, by an Austrian army shell, an English economist with a borrowed rifle.', headline: 'Killed in Red Vienna' },
            result: 'You fire from a window for a day. When the building falls you are arrested.',
            diary: 'The rifle. Arrested.' },
          { label: 'Write it all down for the English papers', effects: 'press+3 cap+2',
            result: 'Your account is printed in the New Statesman. In England it is the first many have heard of it.',
            diary: 'The New Statesman.' },
        ] },

      { id: 'vienna-after-1934', year: 1934, t: 1934.14, title: 'In the cells', if: '!route-wea ~#vienna ' + LIVE,
        venue: { plate: 'prison', label: 'The police prison, Rossauer Lände, Vienna' },
        text: 'February 1934. You were taken with the rifle still warm. The cell holds forty men, most of them socialist railwaymen, and the guards are beating them one by one. A British consular officer has come: he can have you deported tomorrow if you sign a statement that you were led astray by foreign agitators. The railwaymen are watching you. One of them, with a broken hand, shakes his head very slightly.',
        basis: 'An invented consequence of the rogue choice in Vienna, February 1934. Thousands of socialists were arrested after the fighting; nine were executed.',
        real: 'After the February fighting the Austrian government arrested thousands of Social Democrats and hanged nine. Gaitskell was not arrested.',
        check: 'research', facts: ['gaitskell-early'],
        choices: [
          { label: 'Sign, and go home', effects: 'steel-3 health+2 rep-1',
            result: 'You are on the Paris train by noon. You never quite forgive yourself, and you work twice as hard to make up for it.',
            diary: 'Signed. I will make up for it.' },
          { label: 'Refuse to sign', effects: 'steel+4 health-4 fork=vienna34',
            result: 'You stay with the railwaymen. The consul shrugs.',
            diary: 'Refused. Stayed.' },
          { label: 'Sign, and take the railwaymen\'s names out with you', effects: 'state+2 steel+1',
            result: 'You memorise twelve names and addresses. In London you raise money for their families.',
            diary: 'Twelve names.' },
        ] },

      { id: 'gillingham-1935', year: 1935, t: 1935.85, title: 'Selection speech', if: '!route-wea ' + LIVE,
        venue: { plate: 'city', label: 'A Co-operative hall, Gillingham, Kent' },
        text: 'October 1935. The Gillingham Labour Party is choosing its candidate. The dockyard men want someone who will promise peace, disarmament and socialism, in that order. You have written that democracy comes before socialism, and that Hitler must be faced. The other candidate is a pacifist schoolteacher with a fine voice. The chairman, a shipwright, asks you for your three principles, in order.',
        basis: 'Evan Durbin\'s selection speech for Gillingham in 1935, in which he put political democracy above socialism and peace; Gaitskell fought Chatham the same year; both lost.',
        real: 'Durbin stood at Gillingham and Gaitskell at Chatham in 1935, both Medway dockyard seats, and both lost. Durbin told his selection meeting that political democracy came before socialism and before peace.',
        check: 'research', facts: ['durbin-early'],
        choices: [
          { label: 'Democracy first, then socialism, then peace', effects: 'steel+3 order+1 @dunbar+3', historical: true,
            roll: { stat: 'capital', diff: 25,
              pass: { effects: 'rep+2', result: 'They choose you by two votes. In November you lose the seat, but you double the Labour vote.', diary: 'Chosen. Lost, doubled the vote.' },
              fail: { effects: 'rep-1', result: 'They choose the pacifist. He loses.', diary: 'They chose the pacifist.' } } },
          { label: 'Peace first, to win the room', effects: 'steel-2 loyalty+2',
            result: 'They choose you. You lose in November, and feel you had lied a little.',
            diary: 'Won the room. Lied a little.' },
          { label: 'Withdraw: the time is not right', effects: 'cap+2',
            result: 'You go back to the classes and the bureau.',
            diary: 'Withdrew.' },
        ] },

      { id: 'programme-1937', year: 1937, t: 1937.6, title: 'The Immediate Programme', if: '~!route-grammar ~!route-patents ' + LIVE,
        venue: { plate: 'whitehall', label: 'Transport House, Smith Square' },
        text: '1937. The party wants a short programme a Labour government could carry out in five years. The drafting committee is arguing: nationalise the Bank of England, coal, power, transport, yes; the joint-stock banks and steel, perhaps. Gaskell wants it modest enough to be believed. The left wants the commanding heights. It must be ready for conference in October, in one page.',
        basis: 'Labour\'s Immediate Programme (1937), which Gaitskell helped draft: nationalisation of the Bank of England, coal, power and transport, but not the joint-stock banks or steel; Dalton\'s wider ambitions.',
        real: 'Labour\'s Immediate Programme was adopted in 1937. It promised to nationalise the Bank of England, coal, gas and electricity and transport, and to set up a National Investment Board. Gaitskell helped draft it; it left out the joint-stock banks and steel. Most of it was enacted after 1945.',
        check: 'unchecked', facts: ['immediate-programme-1937', 'gaitskell-early'],
        choices: [
          { label: 'Keep it short and believable', effects: 'order+1 state+2 cap+3 @gaskell+4', historical: true,
            result: 'One page, five industries, one investment board. Conference adopts it. In 1945 the civil servants will have it on their desks on the first morning.',
            diary: 'One page. On their desks in 1945.' },
          { label: 'Add steel and the banks', effects: 'state+4 order-2 loyalty-1',
            result: 'You win steel and lose the banks. Steel will be the one fight that is never finished.',
            diary: 'Steel in. Banks out.' },
          { label: 'Add family allowances and a health service', effects: 'state+3 cap+2',
            result: 'The health service goes in, in a sentence. Someone will have to make it real.',
            diary: 'A health service, in a sentence.' },
        ] },

      { id: 'leeds-1937', year: 1937, t: 1937.8, title: 'Leeds South', if: '!route-wea ' + LIVE,
        venue: { plate: 'mill', label: 'A ward meeting, Hunslet, Leeds' },
        text: 'Autumn 1937. A safe Labour seat, Leeds South, is choosing the man who will succeed its old Member at the next election. Mr Dalby has written to friends in Leeds on your behalf. The ward secretaries are railwaymen and engineers who distrust Oxford men. One of them asks whether you have ever done a day\'s work with your hands. The honest answer is no.',
        basis: 'Gaitskell\'s selection for Leeds South in 1937, with Dalton\'s help; he was elected there in July 1945.',
        real: 'Gaitskell was selected for Leeds South in 1937 as prospective candidate, helped by Dalton, and won the seat in 1945. He held it until his death in 1963.',
        check: 'research', facts: ['gaitskell-early'],
        choices: [
          { label: 'Tell the truth, and talk about the WEA classes', effects: 'state+2 cap+2', historical: true,
            roll: { stat: 'capital', diff: 20,
              pass: { effects: 'rep+3 seat+12 set:seat=Leeds_South', result: 'They respect the answer. You are chosen. The seat is yours when the election comes.', diary: 'Leeds South. Chosen.' },
              fail: { effects: 'rep-1', result: 'They choose a railwayman. You wait.', diary: 'A railwayman chosen.' } } },
          { label: 'Lean on Mr Dalby\'s letters', effects: 'fav+3 loyalty+1',
            result: 'You are chosen. Some of the ward secretaries remember how.',
            diary: 'Chosen. Remembered how.' },
          { label: 'Withdraw in favour of the railwayman', effects: 'state+1 loyalty+2',
            result: 'The railwayman is grateful. Mr Dalby is not.',
            diary: 'Withdrew.' },
        ] },

      /* ═══════ Wilmot: Beverley's assistant ═══════ */
      { id: 'beverley-1937', year: 1937, t: 1937.75, title: 'Sir William\'s figures', if: '!route-grammar',
        venue: { plate: 'school', label: 'University College, Oxford' },
        text: 'Autumn 1937. Sir William Beverley, who built the labour exchanges and ran the LSE, has hired you to help with a great study of unemployment and the trade cycle. He is brilliant, vain, and works his assistants to the bone. He wants the figures for every month since 1860. Your fellowship pays three hundred a year. Mary would like to be married.',
        basis: 'Harold Wilson became a research assistant to William Beveridge at University College, Oxford, in 1937, working on unemployment and the trade cycle; he married Mary Baldwin on 1 January 1940.',
        real: 'After his First, Wilson worked as a research assistant to Beveridge on unemployment and the trade cycle and became a lecturer at University College, Oxford, in 1938. He married Mary Baldwin on 1 January 1940.',
        check: 'research', facts: ['wilson-early'],
        choices: [
          { label: 'Do the figures, every month since 1860', effects: 'cap+4 state+2 health-1 @beverley+5', historical: true,
            result: 'You find patterns nobody has seen. Sir William publishes them, under his name, with a kind word for you in the preface.',
            diary: 'Patterns nobody saw. A kind word.' },
          { label: 'Argue with him about the causes', effects: 'cap+3 temper+2 @beverley-2',
            result: 'He shouts. Then he changes a chapter.',
            diary: 'He shouted. He changed a chapter.' },
          { label: 'Get engaged', effects: 'health+3 @mary+8',
            result: 'You buy a ring you cannot afford. The wedding will be on New Year\'s Day, 1940.',
            diary: 'Engaged. New Year\'s Day, 1940.' },
        ] },

      { id: 'trade-cycle-1938', year: 1938, title: 'A Liberal no longer', if: '!route-grammar',
        venue: { plate: 'school', label: 'A seminar room, Oxford' },
        text: '1938. Sir William thinks markets can be made to work with a little help. Your figures say that every slump since 1860 has thrown hundreds of thousands out of work for years, and that nothing in the market will stop it. Mr Cole asks you to join the Labour Party. The Liberals ask you to stand for a hopeless seat. A don asks you to write a dull, thorough book.',
        basis: 'Wilson\'s move from Liberalism to Labour in the late 1930s under the influence of G. D. H. Cole and his work on unemployment.',
        real: 'Wilson had been a Liberal at Oxford; the influence of Cole and his work on unemployment brought him to Labour. He was elected for Ormskirk in 1945.',
        check: 'research', facts: ['wilson-early'],
        choices: [
          { label: 'Join the Labour Party', effects: 'state+3 loyalty+2', historical: true,
            result: 'You pay your subscription at the Oxford City party and are put on the education committee.',
            diary: 'Labour now.' },
          { label: 'Stand for the Liberals', effects: 'order+1 cap+2',
            result: 'You lose your deposit and learn how to make a speech.',
            diary: 'Lost my deposit. Learned to speak.' },
          { label: 'Write the book', effects: 'cap+4',
            result: 'It is dull and thorough, and every economist cites it.',
            diary: 'Dull and thorough. Cited.' },
        ] },
    ],
  };
})();
